import { useCallback, useRef } from 'react';

import { indexShouldBeIncludedInShiftClickedList } from '../functions/index-should-be-included-in-shift-clicked-list.js';
import { LegendItem } from '../types/legend.js';

type ItemSelectionMemory = { [itemId: string]: boolean };

/**
 * Hook for selecting items in a different behavior depending on what keys are pressed during the click event.
 * Modifier keys that right now add behavior:
 *
 * - Shift key: it will select from last non-shift-click up to the new shift-click.
 * - Ctrl / Cmd key: it will add or remove selection without altering the other selections. It will
 * update the `last non-shift click` memory that's relevant for following shift clicks.
 * - Non modified click: it will simply select the clicked item. It will also modify the
 * `last non-shift click` memory relevant for future shift-clicks. If only one item is selected, and
 * it is clicked in this way, all items will be re-selected.
 *
 * @param allItems - the complete list of items to be considered
 * @returns selectItem function that should smart-select with MouseEvent modifiers
 */
export function useKeyboardSelectionShortcuts(
  allItems: LegendItem[],
): (item: LegendItem, event: MouseEvent) => LegendItem[] {
  const buildSelections = useCallback(
    (selected: boolean): ItemSelectionMemory =>
      allItems.reduce((acc: ItemSelectionMemory, item: LegendItem) => {
        acc[item.id] = selected;

        return acc;
      }, {}),
    [allItems],
  );

  const pivot = useRef<number | undefined>();
  const lastIndexClicked = useRef<number | undefined>();
  const itemSelectionMap = useRef<ItemSelectionMemory>(buildSelections(true));

  const newClickIndex = useCallback(
    (item: LegendItem) => allItems.findIndex((it) => it.id === item.id),
    [allItems],
  );

  const updateItemSelectionMap = (
    id: string,
    selected: boolean,
  ): { [itemId: string]: boolean } => {
    const newSelectionMap = { ...itemSelectionMap.current, [id]: selected };

    itemSelectionMap.current = newSelectionMap;

    return newSelectionMap;
  };

  const getCurrentSelection = (
    selectionMap: ItemSelectionMemory,
  ): LegendItem[] =>
    allItems.filter((item: LegendItem) => selectionMap[item.id]);

  const smartSelectionWithShift = (item: LegendItem): LegendItem[] => {
    if (pivot.current === undefined || lastIndexClicked.current === undefined) {
      return simpleSelection(item);
    }

    const newClick = newClickIndex(item);
    const previousLastClick = lastIndexClicked.current as number;
    lastIndexClicked.current = newClick;

    const newItemSelectionMap = { ...itemSelectionMap.current };
    allItems.forEach((item, index) => {
      newItemSelectionMap[item.id] = indexShouldBeIncludedInShiftClickedList(
        index,
        newClick,
        pivot.current!,
        previousLastClick,
        newItemSelectionMap[item.id],
      );
    });

    itemSelectionMap.current = newItemSelectionMap;

    return getCurrentSelection(newItemSelectionMap);
  };

  const smartSelectionWithCtrl = (item: LegendItem): LegendItem[] => {
    const newClick = newClickIndex(item);

    pivot.current = newClick;
    lastIndexClicked.current = newClick;

    const newItemSelectionMap = updateItemSelectionMap(
      item.id,
      !itemSelectionMap.current[item.id],
    );

    return getCurrentSelection(newItemSelectionMap);
  };

  const simpleSelection = (item: LegendItem): LegendItem[] => {
    const currentSelectedSize = Object.values(itemSelectionMap.current).filter(
      (item) => item,
    ).length;
    const newClick = newClickIndex(item);

    pivot.current = newClick;
    lastIndexClicked.current = newClick;

    // clicked item is the only selected item
    if (itemSelectionMap.current[item.id] && currentSelectedSize === 1) {
      const newItemSelectionMap = buildSelections(true);
      itemSelectionMap.current = newItemSelectionMap;

      return getCurrentSelection(newItemSelectionMap);
    }

    itemSelectionMap.current = {
      ...buildSelections(false),
      [item.id]: true,
    };

    return [item];
  };

  const selectItem = (item: LegendItem, event: MouseEvent): LegendItem[] => {
    const { shiftKey, ctrlKey, metaKey } = event;

    // shift key overrides control / cmd key press
    if (shiftKey) {
      return smartSelectionWithShift(item);
    }

    if (ctrlKey || metaKey) {
      return smartSelectionWithCtrl(item);
    }

    return simpleSelection(item);
  };

  return selectItem;
}
